  const sql = `DELETE FROM "matched";
INSERT OR IGNORE INTO "matched" ("text") SELECT b0."text" FROM "source" b0 WHERE (b0."text" REGEXP '^a.c$')`;
  return seam.runner.executeMultiple(seam.db, sql);
